23	/// Mapping function for row-major matrices
24	struct RowMajor {
25	public:
26	    /// Logical rank of tensor
27	    static constexpr int RANK = 2;
28	
29	    /// Index type used for coordinates
30	    using Index = uint32_t;
31	
32	    /// Long index type used for offsets
33	    using LongIndex = int64_t;
34	
35	    /// Logical coordinate
36	    using Shape = Coord<RANK, Index>;
37	
38	    /// Stride vector
39	    using Stride = Coord<RANK, LongIndex>;
40	
41	public:
42	    /// Constructor
43	    CATLASS_HOST_DEVICE
44	    RowMajor(Index rows = 0, Index cols = 0)
45	        : shape_(MakeCoord(rows, cols)), stride_(MakeCoord(LongIndex(cols), LongIndex(1)))
46	    {}
47	
48	    /// Constructor
49	    CATLASS_HOST_DEVICE
50	    RowMajor(Index rows, Index cols, LongIndex ldm)
51	        : shape_(MakeCoord(rows, cols)), stride_(MakeCoord(ldm, LongIndex(1)))
52	    {}
53	
54	    /// Ctor
55	    CATLASS_HOST_DEVICE
56	    RowMajor(Shape shape, Stride stride) : shape_(shape), stride_(stride)
57	    {}
58	
59	    template <class Element>
60	    CATLASS_HOST_DEVICE static RowMajor MakeLayout(Index rows, Index cols)
61	    {
62	#if (defined(CATLASS_ARCH) && CATLASS_ARCH == 3510)
63	        if constexpr (std::is_same_v<Element, float4_e2m1x2_t> || std::is_same_v<Element, float4_e1m2x2_t>) {
64	            return RowMajor(rows, cols, RoundUp<2>(cols));
65	        }
66	#endif
67	        return RowMajor(rows, cols);
68	    }
69	
70	    template <class Element>
71	    CATLASS_HOST_DEVICE static RowMajor MakeLayoutInUb(MatrixCoord const& shape)
72	    {
73	        constexpr uint32_t ELE_NUM_PER_BLK = BytesToBits(BYTE_PER_BLK) / SizeOfBits<Element>::value;
74	        return RowMajor(shape.row(), shape.column(), RoundUp<ELE_NUM_PER_BLK>(shape.column()));
75	    }
76	
77	    /// Returns the offset of a coordinate in linear memory.
78	    /// Assumes coordinate has convention (row, column)
79	    CATLASS_HOST_DEVICE
80	    LongIndex GetOffset(MatrixCoord const& coord) const
81	    {
82	        return LongIndex(coord.row()) * stride_[0] + LongIndex(coord.column());
83	    }
84	
85	    /// Returns the layout of a tile.
86	    CATLASS_HOST_DEVICE
87	    RowMajor GetTileLayout(MatrixCoord const& tileShape) const
88	    {
89	        return RowMajor(tileShape, stride());
90	    }
91	
92	    /// Returns the shape of the layout
93	    CATLASS_HOST_DEVICE
94	    Shape shape() const
95	    {
96	        return shape_;
97	    }
98	
99	    /// Returns the shape of the layout
100	    CATLASS_HOST_DEVICE
101	    Shape& shape()
102	    {
103	        return shape_;
104	    }
105	
106	    /// Returns the shape of the layout
107	    CATLASS_HOST_DEVICE
108	    typename Shape::Index shape(int idx) const
109	    {
110	        return shape_[idx];
111	    }
112	
113	    /// Returns the shape of the layout
114	    CATLASS_HOST_DEVICE
115	    typename Shape::Index& shape(int idx)
116	    {
117	        return shape_[idx];
118	    }
119	
120	    /// Returns the stride of the layout
121	    CATLASS_HOST_DEVICE
122	    Stride stride() const
123	    {
124	        return stride_;
125	    }
126	
127	    /// Returns the stride of the layout
128	    CATLASS_HOST_DEVICE
129	    Stride& stride()
130	    {
131	        return stride_;
132	    }
133	
134	    /// Returns the stride of the layout
135	    CATLASS_HOST_DEVICE
136	    typename Stride::Index stride(int idx) const
137	    {
138	        return stride_[idx];
139	    }
140	
141	    /// Returns the stride of the layout
142	    CATLASS_HOST_DEVICE
143	    typename Stride::Index& stride(int idx)
144	    {
145	        return stride_[idx];
146	    }
147	
148	    /// Returns the length of the layout
149	    CATLASS_HOST_DEVICE
150	    LongIndex Capacity() const
151	    {
152	        return static_cast<LongIndex>(shape_[0]) * stride_[0];
153	    }
154	
155	protected:
156	    //
157	    // Data members
158	    //
159	
160	    /// Shape data member
161	    Shape shape_;
162	
163	    /// Stride data member
164	    Stride stride_;
165	};
