208	#if (defined(CATLASS_ARCH) && CATLASS_ARCH == 3510)
209	        if constexpr (std::is_same_v<Element, float4_e2m1x2_t> || std::is_same_v<Element, float4_e1m2x2_t>) {
210	            return ColumnMajor(rows, cols, RoundUp<2>(rows));
211	        }
212	#endif
213	        return ColumnMajor(rows, cols);
