228	        return ColumnMajor(tileShape, stride());
229	    }
230	
231	    /// Returns the shape of the layout
232	    CATLASS_HOST_DEVICE
233	    Shape shape() const
234	    {
235	        return shape_;
236	    }
237	
238	    /// Returns the shape of the layout
239	    CATLASS_HOST_DEVICE
240	    Shape& shape()
241	    {
242	        return shape_;
243	    }
244	
245	    /// Returns the shape of the layout
246	    CATLASS_HOST_DEVICE
247	    typename Shape::Index shape(int idx) const
248	    {
249	        return shape_[idx];
250	    }
251	
252	    /// Returns the shape of the layout
253	    CATLASS_HOST_DEVICE
254	    typename Shape::Index& shape(int idx)
255	    {
256	        return shape_[idx];
257	    }
258	
259	    /// Returns the stride of the layout
260	    CATLASS_HOST_DEVICE
261	    Stride stride() const
262	    {
263	        return stride_;
264	    }
265	
266	    /// Returns the stride of the layout
267	    CATLASS_HOST_DEVICE
268	    Stride& stride()
269	    {
270	        return stride_;
271	    }
272	
273	    /// Returns the stride of the layout
274	    CATLASS_HOST_DEVICE
275	    typename Stride::Index stride(int idx) const
276	    {
277	        return stride_[idx];
278	    }
279	
280	    /// Returns the stride of the layout
281	    CATLASS_HOST_DEVICE
282	    typename Stride::Index& stride(int idx)
283	    {
284	        return stride_[idx];
285	    }
286	
287	    /// Returns the length of the layout
288	    CATLASS_HOST_DEVICE
289	    LongIndex Capacity() const
290	    {
291	        return static_cast<LongIndex>(shape_[1]) * stride_[1];
292	    }
293	
294	protected:
295	    //
296	    // Data members
297	    //
298	
299	    /// Shape data member
300	    Shape shape_;
301	
302	    /// Stride data member
303	    Stride stride_;
304	};
