306	/// Mapping function for nZ matrices which is col-major inside fractal and row-major between fractal
307	struct nZ {
308	public:
309	    /// Logical rank of tensor
310	    static constexpr int RANK = 4;
311	
312	    /// Index type used for coordinates
313	    using Index = uint32_t;
314	
315	    /// Long index type used for offsets
316	    using LongIndex = int64_t;
317	
318	    /// Logical rank of orgshape
319	    static constexpr int ORG_SHAPE_RANK = 2;
320	
321	    /// Logical coordinate
322	    using OrgShape = Coord<ORG_SHAPE_RANK, Index>;
323	
324	    /// Logical coordinate
325	    using Shape = Coord<RANK, Index>;
326	
327	    /// Stride vector
328	    using Stride = Coord<RANK, LongIndex>;
329	
330	public:
331	    // Methods
332	
333	    /// Constructor
334	    CATLASS_HOST_DEVICE constexpr nZ(
335	        Index orgRows = 0,                 /// Number of rows of origin matrices
336	        Index orgCols = 0,                 /// Number of cols of origin matrices
337	        Index rowsInFractal = 0,           /// Number of rows inside the fractal
338	        Index rowsByFractal = 0,           /// number of rows by the fractal
339	        Index colsInFractal = 0,           /// number of cols inside the fractal
340	        Index colsByFractal = 0,           /// number of cols by the fractal
341	        LongIndex strideRowsInFractal = 0, /// number of elements between adjacent rows inside the fractal
342	        LongIndex strideRowsByFractal = 0, /// number of elements between adjacent fractal rows
343	        LongIndex strideColsInFractal = 0, /// number of elements between adjacent cols inside the fractal
344	        LongIndex strideColsByFractal = 0) /// number of elements between adjacent fractal cols
345	        : orgShape_(MakeCoord(orgRows, orgCols)),
346	          shape_(MakeCoord(rowsInFractal, rowsByFractal, colsInFractal, colsByFractal)),
347	          stride_(MakeCoord(strideRowsInFractal, strideRowsByFractal, strideColsInFractal, strideColsByFractal))
348	    {}
349	
350	    /// Ctor
351	    CATLASS_HOST_DEVICE constexpr nZ(OrgShape orgShape, Shape shape, Stride stride)
352	        : orgShape_(orgShape), shape_(shape), stride_(stride)
353	    {}
354	
355	    /// Make the layout of a coordinate (row, column)
356	    template <class Element>
357	    CATLASS_HOST_DEVICE constexpr static nZ MakeLayout(Index orgRows, Index orgCols)
358	    {
359	        constexpr uint32_t ELE_NUM_PER_C0 = BytesToBits(BYTE_PER_C0) / SizeOfBits<Element>::value;
360	        constexpr uint32_t ELE_NUM_PER_FRACTAL = BytesToBits(BYTE_PER_FRACTAL) / SizeOfBits<Element>::value;
361	        Index rowsRound = RoundUp<ELE_NUM_PER_C0>(orgRows);
362	        Index colsRound = RoundUp<C0_NUM_PER_FRACTAL>(orgCols);
363	        return nZ(
364	            orgRows, orgCols, ELE_NUM_PER_C0, rowsRound / ELE_NUM_PER_C0, C0_NUM_PER_FRACTAL,
365	            colsRound / C0_NUM_PER_FRACTAL, 1, colsRound * ELE_NUM_PER_C0, ELE_NUM_PER_C0, ELE_NUM_PER_FRACTAL);
366	    }
367	
368	    /// Returns the offset of a coordinate in linear memory.
369	    /// Assumes coordinate has convention (row, column)
370	    CATLASS_HOST_DEVICE
371	    LongIndex GetOffset(MatrixCoord const& coord) const
372	    {
373	        return LongIndex(coord.row()) / shape_[0] * stride_[1] + LongIndex(coord.column()) / shape_[2] * stride_[3] +
374	               (LongIndex(coord.row()) % shape_[0]) * stride_[0] + (LongIndex(coord.column()) % shape_[2]) * stride_[2];
375	    }
376	
377	    /// Returns the layout of a tile.
378	    CATLASS_HOST_DEVICE
379	    nZ GetTileLayout(MatrixCoord const& tileOriShape) const
380	    {
381	        auto tileShape = MakeCoord(
382	            shape(0), CeilDiv(tileOriShape.row(), shape(0)), shape(2), CeilDiv(tileOriShape.column(), shape(2)));
383	        return nZ(tileOriShape, tileShape, stride());
384	    }
385	
386	    /// Returns the origin shape of the layout
387	    CATLASS_HOST_DEVICE
388	    typename OrgShape::Index orgShape(int idx) const
389	    {
390	        return orgShape_[idx];
391	    }
392	
393	    /// Returns the origin shape of the layout
394	    CATLASS_HOST_DEVICE
395	    typename OrgShape::Index& orgShape(int idx)
396	    {
397	        return orgShape_[idx];
398	    }
399	
400	    /// Returns the shape of the layout
401	    CATLASS_HOST_DEVICE
402	    Shape shape() const
403	    {
404	        return shape_;
405	    }
406	
407	    /// Returns the shape of the layout
408	    CATLASS_HOST_DEVICE
409	    Shape& shape()
410	    {
411	        return shape_;
412	    }
413	
414	    /// Returns the shape of the layout
415	    CATLASS_HOST_DEVICE
416	    typename Shape::Index shape(int idx) const
417	    {
418	        return shape_[idx];
419	    }
420	
421	    /// Returns the shape of the layout
422	    CATLASS_HOST_DEVICE
423	    typename Shape::Index& shape(int idx)
424	    {
425	        return shape_[idx];
426	    }
427	
428	    /// Returns the stride of the layout
429	    CATLASS_HOST_DEVICE
430	    Stride stride() const
431	    {
432	        return stride_;
433	    }
434	
435	    /// Returns the stride of the layout
436	    CATLASS_HOST_DEVICE
437	    Stride& stride()
438	    {
439	        return stride_;
440	    }
441	
442	    /// Returns the stride of the layout
443	    CATLASS_HOST_DEVICE
444	    typename Stride::Index stride(int idx) const
445	    {
446	        return stride_[idx];
447	    }
448	
449	    /// Returns the stride of the layout
450	    CATLASS_HOST_DEVICE
451	    typename Stride::Index& stride(int idx)
452	    {
453	        return stride_[idx];
454	    }
455	
456	    /// Returns the length of the layout
457	    CATLASS_HOST_DEVICE
458	    LongIndex Capacity() const
459	    {
460	        return static_cast<LongIndex>(stride_[1]) * shape_[1];
461	    }
462	
463	private:
464	    /// Origin Shape data member
465	    OrgShape orgShape_;
466	
467	    /// Shape data member
468	    Shape shape_;
469	
470	    /// Stride data member
471	    Stride stride_;
472	};
