474	/// Mapping function for zN matrices which is row-major inside fractal and col-major between fractal
475	struct zN {
476	public:
477	    /// Logical rank of tensor
478	    static constexpr int RANK = 4;
479	
480	    /// Index type used for coordinates
481	    using Index = uint32_t;
482	
483	    /// Long index type used for offsets
484	    using LongIndex = int64_t;
485	
486	    /// Logical rank of orgshape
487	    static constexpr int ORG_SHAPE_RANK = 2;
488	
489	    /// Logical coordinate
490	    using OrgShape = Coord<ORG_SHAPE_RANK, Index>;
491	
492	    /// Logical coordinate
493	    using Shape = Coord<RANK, Index>;
494	
495	    /// Stride vector
496	    using Stride = Coord<RANK, LongIndex>;
497	
498	public:
499	    // Methods
500	
501	    /// Constructor
502	    CATLASS_HOST_DEVICE constexpr zN(
503	        Index orgRows = 0,                 /// Number of rows of origin matrices
504	        Index orgCols = 0,                 /// Number of cols of origin matrices
505	        Index rowsInFractal = 0,           /// Number of rows inside the fractal
506	        Index rowsByFractal = 0,           /// number of rows by the fractal
507	        Index colsInFractal = 0,           /// number of cols inside the fractal
508	        Index colsByFractal = 0,           /// number of cols by the fractal
509	        LongIndex strideRowsInFractal = 0, /// number of elements between adjacent rows inside the fractal
510	        LongIndex strideRowsByFractal = 0, /// number of elements between adjacent fractal rows
511	        LongIndex strideColsInFractal = 0, /// number of elements between adjacent cols inside the fractal
512	        LongIndex strideColsByFractal = 0) /// number of elements between adjacent fractal cols
513	        : orgShape_(MakeCoord(orgRows, orgCols)),
514	          shape_(MakeCoord(rowsInFractal, rowsByFractal, colsInFractal, colsByFractal)),
515	          stride_(MakeCoord(strideRowsInFractal, strideRowsByFractal, strideColsInFractal, strideColsByFractal))
516	    {}
517	
518	    /// Ctor
519	    CATLASS_HOST_DEVICE constexpr zN(OrgShape orgShape, Shape shape, Stride stride)
520	        : orgShape_(orgShape), shape_(shape), stride_(stride)
521	    {}
522	
523	    /// Make the layout of a coordinate (row, column)
524	    template <class Element>
525	    CATLASS_HOST_DEVICE constexpr static zN MakeLayout(Index orgRows, Index orgCols)
526	    {
527	        constexpr uint32_t ELE_NUM_PER_C0 = BytesToBits(BYTE_PER_C0) / SizeOfBits<Element>::value;
528	        constexpr uint32_t ELE_NUM_PER_FRACTAL = BytesToBits(BYTE_PER_FRACTAL) / SizeOfBits<Element>::value;
529	        Index rowsRound = RoundUp<C0_NUM_PER_FRACTAL>(orgRows);
530	        Index colsRound = RoundUp<ELE_NUM_PER_C0>(orgCols);
531	        return zN(
532	            orgRows, orgCols, C0_NUM_PER_FRACTAL, rowsRound / C0_NUM_PER_FRACTAL, ELE_NUM_PER_C0,
533	            colsRound / ELE_NUM_PER_C0, ELE_NUM_PER_C0, ELE_NUM_PER_FRACTAL, 1, rowsRound * ELE_NUM_PER_C0);
534	    }
535	
536	    CATLASS_HOST_DEVICE
537	    static zN MakeLayoutInL0C(MatrixCoord const& shape)
538	    {
539	        return zN(
540	            shape.row(), shape.column(), C0_NUM_PER_FRACTAL, CeilDiv<C0_NUM_PER_FRACTAL>(shape.row()),
541	            C0_NUM_PER_FRACTAL, CeilDiv<C0_NUM_PER_FRACTAL>(shape.column()), C0_NUM_PER_FRACTAL,
542	            C0_NUM_PER_FRACTAL * C0_NUM_PER_FRACTAL, 1, RoundUp<C0_NUM_PER_FRACTAL>(shape.row()) * C0_NUM_PER_FRACTAL);
543	    }
544	
545	    /// Returns the offset of a coordinate in linear memory.
546	    /// Assumes coordinate has convention (row, column)
547	    CATLASS_HOST_DEVICE
548	    LongIndex GetOffset(MatrixCoord const& coord) const
549	    {
550	        return LongIndex(coord.row()) / shape_[0] * stride_[1] + LongIndex(coord.column()) / shape_[2] * stride_[3] +
551	               (LongIndex(coord.row()) % shape_[0]) * stride_[0] + (LongIndex(coord.column()) % shape_[2]) * stride_[2];
552	    }
553	
554	    /// Returns the layout of a tile.
555	    CATLASS_HOST_DEVICE
556	    zN GetTileLayout(MatrixCoord const& tileOriShape) const
557	    {
558	        auto tileShape = MakeCoord(
559	            shape(0), CeilDiv(tileOriShape.row(), shape(0)), shape(2), CeilDiv(tileOriShape.column(), shape(2)));
560	        return zN(tileOriShape, tileShape, stride());
561	    }
562	
563	    /// Returns the origin shape of the layout
564	    CATLASS_HOST_DEVICE
565	    typename OrgShape::Index orgShape(int idx) const
566	    {
567	        return orgShape_[idx];
568	    }
569	
570	    /// Returns the origin shape of the layout
571	    CATLASS_HOST_DEVICE
572	    typename OrgShape::Index& orgShape(int idx)
573	    {
574	        return orgShape_[idx];
575	    }
576	
577	    /// Returns the shape of the layout
578	    CATLASS_HOST_DEVICE
579	    Shape shape() const
580	    {
581	        return shape_;
582	    }
583	
584	    /// Returns the shape of the layout
585	    CATLASS_HOST_DEVICE
586	    Shape& shape()
587	    {
588	        return shape_;
589	    }
590	
591	    /// Returns the shape of the layout
592	    CATLASS_HOST_DEVICE
593	    typename Shape::Index shape(int idx) const
594	    {
595	        return shape_[idx];
596	    }
597	
598	    /// Returns the shape of the layout
599	    CATLASS_HOST_DEVICE
600	    typename Shape::Index& shape(int idx)
601	    {
602	        return shape_[idx];
603	    }
604	
605	    /// Returns the stride of the layout
606	    CATLASS_HOST_DEVICE
607	    Stride stride() const
608	    {
609	        return stride_;
610	    }
611	
612	    /// Returns the stride of the layout
613	    CATLASS_HOST_DEVICE
614	    Stride& stride()
615	    {
616	        return stride_;
617	    }
618	
619	    /// Returns the stride of the layout
620	    CATLASS_HOST_DEVICE
621	    typename Stride::Index stride(int idx) const
622	    {
623	        return stride_[idx];
624	    }
625	
626	    /// Returns the stride of the layout
627	    CATLASS_HOST_DEVICE
628	    typename Stride::Index& stride(int idx)
629	    {
630	        return stride_[idx];
631	    }
632	
633	    /// Returns the length of the layout
634	    CATLASS_HOST_DEVICE
635	    LongIndex Capacity() const
636	    {
637	        return static_cast<LongIndex>(stride_[3]) * shape_[3];
638	    }
639	
640	private:
641	    /// Origin Shape data member
642	    OrgShape orgShape_;
643	
644	    /// Shape data member
645	    Shape shape_;
646	
647	    /// Stride data member
648	    Stride stride_;
649	};
