652	struct zZ {
653	public:
654	    /// Logical rank of tensor
655	    static constexpr int RANK = 4;
656	
657	    /// Index type used for coordinates
658	    using Index = uint32_t;
659	
660	    /// Long index type used for offsets
661	    using LongIndex = int64_t;
662	
663	    /// Logical rank of orgshape
664	    static constexpr int ORG_SHAPE_RANK = 2;
