#ifndef CATLASS_COORD_HPP
#define CATLASS_COORD_HPP

#include "catlass/catlass.hpp"

namespace Catlass {

/// Statically-sized array specifying Coords within a tensor
template <
    int RANK_,                 ///< Logical rank of coordinate
    class Index_ = uint32_t,   ///< Index type used for each dimension
    class LongIndex_ = int64_t ///< Long index type used for linear offsets
    >
struct Coord {
public:
    // Number of elements in Coord
    static const int RANK = RANK_;

    // Index typen used to store elements
    using Index = Index_;

    // Type used to represent linear offsets
    using LongIndex = LongIndex_;

    // Default ctor initializes uniformly
    CATLASS_HOST_DEVICE constexpr explicit Coord(Index value = Index(0))
    {
        for (int i = 0; i < RANK; ++i) {
            idx[i] = value;
        }
    }

    // Constructs from an array of integers
    CATLASS_HOST_DEVICE constexpr Coord(Index const (&idx_)[RANK])
    {
        for (int i = 0; i < RANK; ++i) {
            idx[i] = idx_[i];
        }
    }

    CATLASS_HOST_DEVICE
    int Argmin() const
    {
        return ArgminImpl<1>(0);
    }

    // Returns the index of the dimension with greatest value
    CATLASS_HOST_DEVICE
    int Argmax() const
    {
        return ArgmaxImpl<1>(0);
    }

    // Returns true if Coord is non-zero
    CATLASS_HOST_DEVICE
    explicit operator bool() const
    {
        return AnyImpl<0>();
    }

    // Return true if Coord is uniformly zero.
    CATLASS_HOST_DEVICE
    bool operator!() const
    {
        return !AnyImpl<0>();
    }

    // Element-wise addition
    CATLASS_HOST_DEVICE
    Coord operator+(Coord const& b) const
    {
        Coord c;
        AddCoordImpl<0>(c, b);
        return c;
    }

    // Add a scalar to each element
    CATLASS_HOST_DEVICE
    Coord operator+(const Index val) const
    {
        Coord c;
        AddScalarImpl<0>(c, val);
        return c;
    }

    // Element-wise subtraction
    CATLASS_HOST_DEVICE
    Coord operator-(Coord const& b) const
    {
        Coord c;
        SubCoordImpl<0>(c, b);
        return c;
    }

    // Subtract a scalar from each element
    CATLASS_HOST_DEVICE
    Coord operator-(Index const val) const
    {
        Coord c;
        SubScalarImpl<0>(c, val);
        return c;
    }

    // Element-wise multiply
    CATLASS_HOST_DEVICE
    Coord operator*(Coord const& b) const
    {
        Coord c;
        MulCoordImpl<0>(c, b);
        return c;
    }

    // Element-wise division
    CATLASS_HOST_DEVICE
    Coord operator/(Coord const& b) const
    {
        Coord c;
        DivCoordImpl<0>(c, b);
        return c;
    }

    // Element-wise mod
    CATLASS_HOST_DEVICE
    Coord operator%(Coord const& b) const
    {
        Coord c;
        ModCoordImpl<0>(c, b);
        return c;
    }

    // In-place addition
    CATLASS_HOST_DEVICE
    Coord& operator+=(Coord const& b)
    {
        PlusEqualImpl<0>(b);
        return *this;
    }

    // In-place equal
    CATLASS_HOST_DEVICE
    bool operator==(Coord const& b) const
    {
        return EqualCoordImpl<0>(b);
    }

    // In-place equal
    CATLASS_HOST_DEVICE
    bool operator==(Index const val) const
    {
        return EqualScalarImpl<0>(val);
    }

    // Member acces operator
    CATLASS_HOST_DEVICE
    Index& operator[](int dim)
    {
        return idx[dim];
    }

    // Member access operator
    CATLASS_HOST_DEVICE
    Index const& operator[](int dim) const
    {
        return idx[dim];
    }

    // Gets the index of a given Coord element
    template <int DIM>
    CATLASS_HOST_DEVICE Index& At()
    {
        return idx[DIM];
    }

    // Access via index; may limit unrolling potential
    CATLASS_HOST_DEVICE
    Index& At(int dim)
    {
        return idx[dim];
    }

    // Gets the index of a given Coord element
    template <int DIM>
    CATLASS_HOST_DEVICE Index const& At() const
    {
        return idx[DIM];
    }

    // Access via index; may limit unrolling potential
    CATLASS_HOST_DEVICE
    Index const& At(int dim) const
    {
        return idx[dim];
    }

    template <int... Is>
    CATLASS_HOST_DEVICE auto GetCoordByAxis() const
    {
        Index idx_[sizeof...(Is)]{idx[Is]...};
        return Coord<sizeof...(Is), Index, LongIndex>{idx_};
    }

    CATLASS_HOST_DEVICE
    static Coord Min(Coord const& a, Coord const& b)
    {
        Coord res;
        for (int i = 0; i < RANK; ++i) {
            res[i] = a[i] < b[i] ? a[i] : b[i];
        }
        return res;
    }

private:
    template <int N>
    CATLASS_HOST_DEVICE int ArgminImpl(int i) const
    {
        if constexpr (N == RANK) {
            return i;
        } else {
            return ArgminImpl<N + 1>(idx[N] < idx[i] ? N : i);
        }
    }

    template <int N>
    CATLASS_HOST_DEVICE int ArgmaxImpl(int i) const
    {
        if constexpr (N == RANK) {
            return i;
        } else {
            return ArgmaxImpl<N + 1>(idx[N] > idx[i] ? N : i);
        }
    }

    template <int N>
    CATLASS_HOST_DEVICE bool AnyImpl() const
    {
        if constexpr (N == RANK) {
            return false;
        } else {
            return idx[N] || AnyImpl<N + 1>();
        }
    }

    template <int N>
    CATLASS_HOST_DEVICE void AddCoordImpl(Coord& c, Coord const& b) const
    {
        if constexpr (N < RANK) {
            c.idx[N] = idx[N] + b.idx[N];
            AddCoordImpl<N + 1>(c, b);
        }
    }

    template <int N>
    CATLASS_HOST_DEVICE void AddScalarImpl(Coord& c, Index const val) const
    {
